bounded_host_request.command:
set -eu
python3 - <<'PY'
import subprocess,sys,os
def sh(a):
 p=subprocess.run(a,text=True,capture_output=True,timeout=30)
 return p.returncode,p.stdout.strip(),p.stderr.strip()
rc,label,_=sh(['docker','inspect','deploy-gaybbs-1','--format','{{index .Config.Labels "com.docker.compose.project.config_files"}}'])
if rc or not label:sys.exit(51)
paths=[s.strip() for s in label.split(',') if s.strip()]
if not paths:sys.exit(52)
if len(paths)>8:sys.exit(53)
if any(not p.startswith('/') for p in paths):sys.exit(54)
if any(not os.path.isfile(p) for p in paths):sys.exit(55)
args=['docker','compose']
for p in paths:args+=['-f',p]
args+=['-p','deploy','config','-q']
rc,_,err=sh(args)
if rc:
 if 'no such file' in err.lower():sys.exit(56)
 if 'permission' in err.lower():sys.exit(57)
 sys.exit(58)
rc,_,err=sh(args[:-2]+['--dry-run','up','-d','--no-deps','gaybbs'])
if rc:
 if 'unknown flag' in err.lower():sys.exit(59)
 sys.exit(60)
sys.exit(0)
PY
